/bin/bash -lc "cat > /tmp/inspect-env.js <<'EOF'
const fs=require('fs');
const p='.env.local';
const lines=fs.readFileSync(p,'utf8').split(/\\r?\\n/);
const out=[];
for(const line of lines){
 const m=line.match(/"'^'"\\s*(?:export\\s+)?([A-Za-z_][A-Za-z0-9_]*)\\s*=(.*)"'$/);
 if(!m) continue;
 const value=m[2].trim();
 out.push({name:m[1], nonempty:Boolean(value), validStripeSecret: /''^sk_(test|live)_/.test(value.replace(/''^['"'\"]|['\"]"'$/g,'"''))});
}
console.log(JSON.stringify(out));
EOF
node /tmp/inspect-env.js && git check-ignore -v .env.local && git status --short"

